import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df['exit_in_window'] = df['exit_in_window'].fillna('')
    df['in_force_now'] = df['in_force_now'].fillna('')
    df['exit_event_date'] = pd.to_datetime(df['exit_event_date'], errors='coerce')
    df['row_kind'] = df['row_kind'].fillna('')

    valid = df[df['row_kind'].isin(['counted', ''])]

    dept_avg_hc = {
        'Engineering': 410.1,
        'Marketing': 145.9,
        'Sales': 345.8,
        'Finance': 141.9,
        'Support': 267.5
    }

    window_start = pd.Timestamp('2025-10-25')
    window_end = pd.Timestamp('2026-10-24')

    exits_window = valid[
        (valid['exit_event_date'] >= window_start) &
        (valid['exit_event_date'] <= window_end)
    ]

    dept_exits = exits_window.groupby('department').size().reset_index(name='exits')

    dept_exits['avg_hc'] = dept_exits['department'].map(dept_avg_hc)
    dept_exits['attrition_rate'] = dept_exits['exits'] / dept_exits['avg_hc']

    dept_exits_sorted = dept_exits.sort_values('attrition_rate', ascending=False)

    attrition_results = [
        {"name": row['department'], "value": round(row['attrition_rate'], 4)}
        for _, row in dept_exits_sorted.iterrows()
    ]

    result['segments'].append({
        "segment_column": "department",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": attrition_results
    })

    dept_exits_count = [
        {"name": row['department'], "value": float(row['exits'])}
        for _, row in dept_exits_sorted.iterrows()
    ]

    result['segments'].append({
        "segment_column": "department",
        "metric_column": "exit_event_date",
        "aggregation": "count",
        "label": "exits_in_window",
        "results": dept_exits_count
    })

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

try:
    result['assumptions'].append(
        "Attrition rate = exits in 12-month window (25 Oct 2025 – 24 Oct 2026) divided by domain-provided average headcount per department."
    )
    result['assumptions'].append(
        "Average headcount per department sourced from domain facts, not recomputed from rows."
    )
    result['assumptions'].append(
        "Only rows with exit_event_date in the 12-month window are counted as separations."
    )
    result['assumptions'].append(
        "row_kind filter applied: only 'counted' or blank rows included."
    )
except Exception:
    pass

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
    _head_df = df.head(5).replace({float('nan'): None})
    result['head_preview'] = _head_df.to_dict('records')
except Exception:
    pass

try:
    result['dtypes_summary'] = {str(k): str(v) for k, v in df.dtypes.items()}
    result['non_null'] = {str(k): int(v) for k, v in df.notna().sum().items()}
    result['n_rows'] = int(len(df))
except Exception:
    pass

try:
