try:
    in_force = df[(df['in_force_now'] == 'yes') & (~df['Worker_Type'].isin(['Contractor', 'Agency Worker']))]
    in_force = in_force.copy()
    in_force['fte_pay'] = in_force['Annual_Salary'] / in_force['FTE'].replace(0, float('nan'))
    in_force = in_force[in_force['Gender'].isin(['Male', 'Female'])]

    levels = sorted(in_force['Job_Level'].dropna().unique())

    mean_gap_results = []
    median_gap_results = []

    for lvl in levels:
        sub = in_force[in_force['Job_Level'] == lvl]
        males = sub[sub['Gender'] == 'Male']['fte_pay'].dropna()
        females = sub[sub['Gender'] == 'Female']['fte_pay'].dropna()
        if len(males) < 11 or len(females) < 11:
            continue
        m_mean = males.mean()
        f_mean = females.mean()
        m_med = males.median()
        f_med = females.median()
        mean_gap = (m_mean - f_mean) / m_mean if m_mean != 0 else float('nan')
        median_gap = (m_med - f_med) / m_med if m_med != 0 else float('nan')
        mean_gap_results.append({"name": str(lvl), "value": round(mean_gap, 4)})
        median_gap_results.append({"name": str(lvl), "value": round(median_gap, 4)})

    result['segments'].append({
        "segment_column": "Job_Level",
        "metric_column": "Annual_Salary",
        "aggregation": "ratio",
        "label": "unadjusted_gender_pay_gap_mean",
        "results": mean_gap_results
    })

    result['segments'].append({
        "segment_column": "Job_Level",
        "metric_column": "Annual_Salary",
        "aggregation": "ratio",
        "label": "unadjusted_gender_pay_gap_median",
        "results": median_gap_results
    })

    result['assumptions'].append("Pay gap = (men's mean FTE pay − women's mean FTE pay) ÷ men's mean FTE pay; unadjusted; in-force employees only; contractors excluded; groups < 11 suppressed.")
    result['assumptions'].append("FTE-adjusted pay = Annual_Salary / FTE; rows with FTE=0 excluded.")
    result['assumptions'].append("Non-binary / unspecified gender excluded from gap calculation per policy.")

