        median_gap = (men_median - women_median) / men_median if men_median != 0 else float('nan')
        mean_gap_results.append({"name": str(lvl), "value": round(mean_gap, 4)})
        median_gap_results.append({"name": str(lvl), "value": round(median_gap, 4)})

