try:
    df['exit_event_date'] = pd.to_datetime(df['exit_event_date'], errors='coerce')

    window_2026_start = pd.Timestamp('2026-01-01')
    window_2026_end = pd.Timestamp('2026-10-31')
    window_2025_start = pd.Timestamp('2025-01-01')
    window_2025_end = pd.Timestamp('2025-12-31')

    exits_2026 = df[
        (df['exit_event_date'] >= window_2026_start) &
        (df['exit_event_date'] <= window_2026_end)
    ]
    exits_2025 = df[
        (df['exit_event_date'] >= window_2025_start) &
        (df['exit_event_date'] <= window_2025_end)
    ]

    avg_hc_2026 = 958.5
    avg_hc_2025 = 921.8

    n_exits_2026 = len(exits_2026)
    n_exits_2025 = len(exits_2025)

    rate_2026 = n_exits_2026 / avg_hc_2026
    rate_2025 = n_exits_2025 / avg_hc_2025

    result['segments'].append({
        "segment_column": "exit_event_date",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": [
            {"name": "2025", "value": round(rate_2025, 4)},
            {"name": "2026", "value": round(rate_2026, 4)},
        ]
    })

    vol_cats = ['Voluntary']
    vol_exits_2026 = exits_2026[exits_2026['Termination_Category'].isin(vol_cats)]
    vol_exits_2025 = exits_2025[exits_2025['Termination_Category'].isin(vol_cats)]

    vol_rate_2026 = len(vol_exits_2026) / avg_hc_2026
    vol_rate_2025 = len(vol_exits_2025) / avg_hc_2025

    result['segments'].append({
        "segment_column": "exit_event_date",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "voluntary_attrition_rate",
        "results": [
            {"name": "2025", "value": round(vol_rate_2025, 4)},
            {"name": "2026", "value": round(vol_rate_2026, 4)},
        ]
    })

    for dept in df['Department'].dropna().unique():
        dept_exits_2026 = exits_2026[exits_2026['Department'] == dept]
        dept_exits_2025 = exits_2025[exits_2025['Department'] == dept]
