            'Sales': 213.0, 'Operations': 118.2, 'Support': 183.2,
            'Engineering': 271.1, 'Marketing': 96.6, 'Finance': 76.9, 'Legal': 6.0
        }
        dept_hc = dept_hc_map.get(dept, None)
