            dr_2026 = len(dept_exits_2026) / dept_hc
            dr_2025 = len(dept_exits_2025) / dept_hc
        else:
            continue

    dept_rows = []
    for dept in df['Department'].dropna().unique():
        dept_hc_map = {
            'Sales': 213.0, 'Operations': 118.2, 'Support': 183.2,
            'Engineering': 271.1, 'Marketing': 96.6, 'Finance': 76.9, 'Legal': 6.0
        }
        dept_hc = dept_hc_map.get(dept, None)
