        dept_rows.append({"name": f"{dept}|2025", "value": round(d25, 4)})
        dept_rows.append({"name": f"{dept}|2026", "value": round(d26, 4)})

    result['segments'].append({
        "segment_column": "Department|exit_event_date",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
