        lvl_rows.append({"name": f"{lvl}|2025", "value": round(l25, 4)})
        lvl_rows.append({"name": f"{lvl}|2026", "value": round(l26, 4)})

    result['segments'].append({
        "segment_column": "Job_Level|exit_event_date",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": lvl_rows
    })

    result['assumptions'].append(
