import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    df['exit_in_window'] = df['exit_in_window'].astype(str).str.strip().str.lower()
    df['in_force_now'] = df['in_force_now'].astype(str).str.strip().str.lower()

    avg_hc_by_dept = {
        'Support': 56.2,
        'Sales': 95.2,
        'Marketing': 37.7,
        'Finance': 28.2,
        'Engineering': 82.6,
        'Operations': 43.1,
    }

    exits_in_window = df[df['exit_in_window'] == 'yes'].copy()
    exits_by_dept = exits_in_window.groupby('Department').size().reset_index(name='exits')

    dept_results = []
    for _, row in exits_by_dept.iterrows():
        dept = row['Department']
        exits = row['exits']
        avg_hc = avg_hc_by_dept.get(dept, None)
        if avg_hc and avg_hc > 0:
            rate = exits / avg_hc
            dept_results.append({"name": dept, "value": round(rate, 4)})

    dept_results_sorted = sorted(dept_results, key=lambda x: x['value'], reverse=True)

    result['segments'].append({
        "segment_column": "Department",
        "metric_column": "exit_in_window",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": dept_results_sorted
    })

    exits_by_dept_dict = dict(zip(exits_by_dept['Department'], exits_by_dept['exits']))
    exits_count_results = [
        {"name": dept, "value": float(cnt)}
        for dept, cnt in sorted(exits_by_dept_dict.items(), key=lambda x: x[1], reverse=True)
    ]

    result['segments'].append({
        "segment_column": "Department",
        "metric_column": "exit_in_window",
        "aggregation": "count",
        "label": "separations_in_window",
        "results": exits_count_results
    })

    result['assumptions'].append(
        "Attrition rate = exits in 12-month window (exit_in_window=='yes') / domain-pack average headcount per department."
    )
    result['assumptions'].append(
        "Average headcount by department taken from domain facts: Support 56.2, Sales 95.2, Marketing 37.7, Finance 28.2, Engineering 82.6, Operations 43.1."
    )
    result['assumptions'].append(
        "Exits counted by the department the person left from (exit_in_window row's Department)."
    )

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

